"""Compile and measure the exact-zero candidate, without changing public sources."""
import argparse,base64,json,os,shutil,statistics,subprocess,time,traceback
from pathlib import Path
from prepare_vco1_portable import ROOT,sha,write
from prepare_zero_voice import RUST
from joint_cycles_analysis import require
def main():
 parser=argparse.ArgumentParser();parser.add_argument('--attempt',type=int,default=1);args=parser.parse_args();work=ROOT/f'references-local/voice-zero-bench{args.attempt:02d}';out=f'evidence/voice_zero_bench{args.attempt:02d}.json';require(not work.exists() and not (ROOT/out).exists(),'exclusive bench');inp=json.loads((ROOT/'evidence/voice_zero_inputs01.json').read_text(encoding='utf8'));require(inp['passed'],'bank admitted');names=[*RUST,'tools/run_zero_voice.py','tools/prepare_zero_voice.py','docs/VOZ_CEROS_PROTOCOLO.md','evidence/voice_zero_inputs01.json'];before={n:sha(ROOT/n) for n in names};private={o['path']:o['sha256'] for o in inp['outputs']};lib='references-local/voice-block-library02/librf_d_circuit.rlib';private[lib]=sha(ROOT/lib);qa=json.loads((ROOT/'evidence/voice_extended_tests01.json').read_text(encoding='utf8'));require(private[lib]==qa['public_block_library_sha256'],'frozen library');compiler=json.loads((ROOT/'evidence/voice_block_library02.json').read_text(encoding='utf8'))['compiler'];require(sha(Path(compiler['path']))==compiler['sha256'],'compiler');require(shutil.disk_usage(ROOT).free>=1024**3+96*1024**2,'reserve');work.mkdir();exe=work/'bench.exe';env=os.environ.copy();env['PATH']='C:/msys64/mingw64/bin;C:/msys64/ucrt64/bin;'+env['PATH'];commands=[];replays=[];r=dict(passed=False,source_sha256=before,private_used_sha256=private,compiler=compiler,new_library_compile=False,new_cargo_cache=False,lab_stack_bytes=33554432)
 def run(cmd,limit):
  t=time.perf_counter();p=subprocess.run(cmd,cwd=ROOT,env=env,capture_output=True,text=True,encoding='utf8',timeout=limit,creationflags=subprocess.CREATE_NO_WINDOW);return dict(command=cmd,exit_code=p.returncode,stdout=p.stdout,stderr=p.stderr,wall_s=time.perf_counter()-t)
 try:
  for cmd,limit in [([compiler['path'],'--edition=2021','-C','opt-level=2','-C','strip=symbols','-C','link-arg=-Wl,--stack,33554432',RUST[-1],'--extern','rf_d_circuit='+str(ROOT/lib),'-o',str(exe)],120),([str(exe),str(ROOT/'references-local/voice-zero-inputs01/pairs.bin')],300)]:
   q=run(cmd,limit);commands.append(q)
   if q['exit_code']:replays.append(run(cmd,limit));require(False,'bench compile/numeric rejection')
  lines=q['stdout'].splitlines();require(lines[-1]=='ZERO_BENCH_PASSED,168,1834,5' and 'STAMPS_PASSED,168,211138' in lines and 'ERRORS_PASSED,6' in lines and any(l.startswith('IEEE_PASSED,1280,') for l in lines),'whole measured coverage');rounds=[list(map(int,l.split(',')[1:])) for l in lines if l.startswith('ROUND,')];a=statistics.median(x[1] for x in rounds);b=statistics.median(x[2] for x in rounds);worst=max(x[2]/x[1] for x in rounds);storage=next(list(map(int,l.split(',')[1:])) for l in lines if l.startswith('STORAGE,'));r.update(passed=True,numeric_bank_exact=True,ieee_cases=1280,signed_zero_negative_control=True,error_policy_checks=6,complete_stamp_bit_fields=168*211138,rounds=rounds,median_ratio=b/a,worst_round_ratio=worst,cost_utility_passed=b<=.95*a and worst<=1.05,solver_scratch_bytes=storage,production_promoted=False,physical_fidelity=False,real_time=False)
 except Exception:r['failure']=traceback.format_exc();r['failed_source_base64']={n:base64.b64encode((ROOT/n).read_bytes()).decode() for n in names if n.endswith(('.py','.rs'))}
 r.update(commands=commands,replays=replays,source_sha256_after={n:sha(ROOT/n) for n in names},private_used_sha256_after={n:sha(ROOT/n) for n in private},outputs=[dict(path=p.relative_to(ROOT).as_posix(),sha256=sha(p),bytes=p.stat().st_size) for p in work.iterdir() if p.is_file()]);require(before==r['source_sha256_after'] and private==r['private_used_sha256_after'],'stable bench inputs');write(out,r);print('ZERO_BENCH',r['passed'],r.get('median_ratio'),r.get('cost_utility_passed'),r.get('failure',''),flush=True);require(r['passed'],'exact-zero numeric bank')
if __name__=='__main__':main()
